import{_ as e,o as l,c as a,f as o}from"./chunks/framework.kvohTzd7.js";const O=JSON.parse('{"title":"【実機レビュー】POCO M7 Pro 5GにカスタムROM「Halcyon」を導入！HyperOS 3・GSIとの違いと導入手順","description":"POCO M7 Pro 5G（beryl）にカスタムROM「Halcyon」を導入した実機レビュー。純正HyperOS 3やGSIとの体感差、通知バグや通話・指紋認証の解消、導入時の注意点をまとめています。","frontmatter":{"title":"【実機レビュー】POCO M7 Pro 5GにカスタムROM「Halcyon」を導入！HyperOS 3・GSIとの違いと導入手順","date":"2026-11-22","description":"POCO M7 Pro 5G（beryl）にカスタムROM「Halcyon」を導入した実機レビュー。純正HyperOS 3やGSIとの体感差、通知バグや通話・指紋認証の解消、導入時の注意点をまとめています。","tags":["Android"],"headerimage":"https://media.yunfie.date/image.webp?url=https://hlcyn.org/hero.webp"},"headers":[],"relativePath":"posts/poco-m7-pro-5g-halcyon-custom-rom-review/index.md","filePath":"posts/2026/poco-m7-pro-5g-halcyon-custom-rom-review.md","lastUpdated":1795318443000}'),r={name:"posts/poco-m7-pro-5g-halcyon-custom-rom-review/index.md"};function d(i,t,n,p,s,y){return l(),a("div",null,[...t[0]||(t[0]=[o('<p>POCO M7 Pro 5G（コードネーム <code>beryl</code>）に、カスタムROM「Halcyon Project」の公式ビルド（Official）を入れました。これまで純正のHyperOS 3とGSIを行き来して使っていましたが、ようやく普段使いで不満の少ない環境に落ち着きました。</p><h2 id="halcyonに乗り換えた経緯" tabindex="-1">Halcyonに乗り換えた経緯 <a class="header-anchor" href="#halcyonに乗り換えた経緯" aria-label="Permalink to &quot;Halcyonに乗り換えた経緯&quot;">​</a></h2><p>MediaTek Dimensity 7025 Ultraを積んだPOCO M7 Pro 5Gは、純正のHyperOS 3だと動作のもたつきが気になります。そのため、HyperOS 4のアップデート対象外になる前からブートローダーをアンロックして別の環境を探していました。</p><p>ただ、この機種は専用のカスタムROMがまだ多くありません。しばらくはGSIを入れて使っていましたが、GSIでも動作の重さはあまり変わらず、通話と指紋認証が使えないという日常使いには厳しい問題が残りました。そこに端末自体がHyperOS 4の対象外になったこともあり、公式OSへ戻す理由もなくなったため、Halcyon Projectの公式サポート対象としてビルドが配布されている本ROMを試すことにしました。</p><p>ちなみに <code>beryl</code> 向けのビルドはユニファイドビルドになっていて、ハードウェア構成が共通するRedmi Note 14 5G / 14 SE / 15R Proにも対応しています。</p><h2 id="純正hyperos-3・gsiとの違いと使ってみた感想" tabindex="-1">純正HyperOS 3・GSIとの違いと使ってみた感想 <a class="header-anchor" href="#純正hyperos-3・gsiとの違いと使ってみた感想" aria-label="Permalink to &quot;純正HyperOS 3・GSIとの違いと使ってみた感想&quot;">​</a></h2><p>3つの環境を使い比べた体感の違いは以下の通りです。</p><table tabindex="0"><thead><tr><th style="text-align:left;">比較項目</th><th style="text-align:left;">純正 HyperOS 3</th><th style="text-align:left;">GSI環境</th><th style="text-align:left;">Halcyon（専用ROM）</th></tr></thead><tbody><tr><td style="text-align:left;">パフォーマンス・滑らかさ</td><td style="text-align:left;">悪い（もたつきあり）</td><td style="text-align:left;">悪い</td><td style="text-align:left;">滑らかで軽快</td></tr><tr><td style="text-align:left;">通話・指紋認証</td><td style="text-align:left;">利用可能</td><td style="text-align:left;">利用不可</td><td style="text-align:left;">問題なく利用可能</td></tr><tr><td style="text-align:left;">バックグラウンド通知</td><td style="text-align:left;">来なくなるバグあり</td><td style="text-align:left;">改善</td><td style="text-align:left;">安定して届く</td></tr><tr><td style="text-align:left;">外部ランチャー＋ジェスチャー</td><td style="text-align:left;">制限あり</td><td style="text-align:left;">利用可能</td><td style="text-align:left;">そのまま利用可能</td></tr><tr><td style="text-align:left;">バッテリー持ち</td><td style="text-align:left;">標準</td><td style="text-align:left;">—</td><td style="text-align:left;">HyperOS 3より気持ち良い程度</td></tr></tbody></table><p>実際に使い始めてすぐ感じたのは、動作の滑らかさです。純正のHyperOS 3を使っていた頃のもたつきが消え、スクロールやアプリ切り替えが軽快になりました。GSIで困っていた通話と指紋認証も専用ROMなら問題なく動きます。</p><p>HyperOSに長らく残っている「バックグラウンドで通知が来なくなるバグ」も、HyperOSから離れたことで解消しました。また、外部ランチャーを使ってもジェスチャーナビゲーションがそのまま動くのも助かります。純正環境ではここが制限されがちなので、好きなランチャーで操作できるだけでも使い勝手が変わります。</p><p>バッテリー持ちは劇的に伸びたわけではなく、「HyperOS 3の頃より少し良くなったかな」と感じる程度です。動作が軽くなって通知も安定しつつ、電池持ちが悪化していないので個人的には満足しています。</p><p>更新の手軽さも変わりました。Calla 17.0以降はOTAアップデートに対応しており、毎回PCへ繋いで手動で焼き直さなくても、端末上からそのままアップデートを適用できます。</p><h2 id="ビルド構成-gms版とvanilla版" tabindex="-1">ビルド構成（GMS版とVanilla版） <a class="header-anchor" href="#ビルド構成-gms版とvanilla版" aria-label="Permalink to &quot;ビルド構成（GMS版とVanilla版）&quot;">​</a></h2><p>Halcyon Projectの公式ダウンロードページでは、GMS版とVanilla版の2種類が配布されています。</p><p>Bloom 16.0以降のGMSビルドには必要最小限のGoogleアプリセットが標準で入っているため、余計なプリインストールアプリを増やさずにGoogleサービスを使い始められます。Googleサービス自体を入れたくない人向けに、Vanillaビルドも引き続き用意されています。</p><h2 id="導入手順と注意点" tabindex="-1">導入手順と注意点 <a class="header-anchor" href="#導入手順と注意点" aria-label="Permalink to &quot;導入手順と注意点&quot;">​</a></h2><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>ブートローダーのアンロックおよびカスタムROMの導入はメーカー保証の対象外となり、作業中に端末内のデータはすべて消去されます。手順やファームウェアのバージョンを誤ると起動不能（文鎮化）になるリスクがあるほか、環境によっては銀行系アプリや決済アプリ、一部ゲームなどが正常に動作しなくなる場合があります。実施する場合は必ず事前にバックアップを取り、自己責任で行ってください。</p></div><p>カスタムROMを入れる前提として、先にブートローダーアンロックを済ませておく必要があります。Xiaomi HyperOS端末のアンロック申請方法は、以下の記事がわかりやすいです。</p><p><a href="https://note.com/reindex/n/n44b7c62f6f28" target="_blank" rel="noreferrer">Xiaomi HyperOSデバイスのBLU申請 (グローバル)｜Re*Index. (ot_inc)</a></p><p>2026年8月以降のビルド（Callaなど）ではベースがHyperOS 3へ移行し、カーネルも6.12へ更新されています。そのため、導入前にファームウェアのバージョンを合わせておく必要があります。</p><ol><li>2026年8月以降のビルドを入れる前に、端末のファームウェアを <code>3.0.302.0 WOQMIXM</code>（OS 3.0.3xxベース）にしておく。</li><li>FastbootモードでPCと接続し、<code>fastboot flash vendor_boot --slot=all vendor_boot.img</code> でリカバリを書き込む。</li><li>リカバリモードでFormat dataを実行し、<code>Apply update &gt; Apply from ADB</code> から <code>adb sideload</code> でHalcyonのZIPファイルを焼く。</li></ol><p>ファームウェアのバージョンが合っていないと起動不能になる恐れがあるので、作業前に公式Wikiと最新アナウンスは必ず確認しておいた方が安全です。</p><hr><p>HyperOS 3の重さや通知バグ、GSIの制約にモヤモヤしていたPOCO M7 Pro 5Gですが、Halcyonを入れてようやく素直に使えるメイン環境になりました。HyperOS 4の対象外になったあともこの端末を使い続けたい人には、かなり現実的な乗り換え先だと思います。</p>',24)])])}const h=e(r,[["render",d]]);export{O as __pageData,h as default};
